	@Test
	void stableSortingMatchesJdkAcrossEmptySingletonAndPartitionBoundaries() {
		for (int length : new int[] { 0, 1, 31, 8192, 8193, 32768, 32769, 32770, 32771, 32772, 34904, 40001,
				65536, 65537, 131073 }) {
			Random random = new Random(42);
			Row[] input = new Row[length];
			for (int i = 0; i < input.length; i++) {
				input[i] = new Row(random.nextInt(17), i);
			}
			Row[] expected = input.clone();
			Comparator<Row> byKey = Comparator.comparingInt(Row::key);
			Arrays.sort(expected, byKey);
			ThreadLocal<Boolean> admitted = new ThreadLocal<>();
			AtomicInteger activations = new AtomicInteger();
			AtomicInteger closes = new AtomicInteger();
			try (QueryExecutionContext.Activation source = QueryExecutionContext.activateReplaySafepoint(() -> {
			}, () -> () -> {
				assertNull(admitted.get(), "each independent task must restore the worker before the next task");
				admitted.set(true);
				activations.incrementAndGet();
				return () -> {
					admitted.remove();
					closes.incrementAndGet();
				};
			})) {
				ContextAwareArraySorter.sort(input, (left, right) -> {
					assertEquals(Boolean.TRUE, admitted.get());
					return byKey.compare(left, right);
				}, QueryExecutionContext.captureReplayContext());
				assertArrayEquals(expected, input, "stable sort must match the JDK for length " + length);
				assertEquals(activations.get(), closes.get(), "all task capabilities must be closed");
				assertNull(admitted.get(), "the caller's thread must not retain worker admission");
				int parallelism = ForkJoinPool.getCommonPoolParallelism();
				if (length <= 8192 || parallelism == 1) {
					assertEquals(1, activations.get(), "sequential sorting owns one bounded context");
				} else {
					int granularity = (int) Math.max(8192, length / (4L * parallelism));
					// A child of an oversized quarter split contains at least granularity / 4 elements.
					int maximumLeaves = length / (granularity / 4);
					assertTrue(activations.get() <= 2 * maximumLeaves + Integer.numberOfTrailingZeros(
							Integer.highestOneBit(maximumLeaves)), "activations must scale with tasks, not comparisons");
					assertTrue(activations.get() > 1, "large sorting must retain parallel decomposition");
				}
			}
		}
	}

