	@Test
	void recursiveQuarterLeavesCoverOddAndMixedDepthRanges() {
		Assumptions.assumeTrue(ForkJoinPool.getCommonPoolParallelism() >= 2);
		LeafFixture[] fixtures = {
				new LeafFixture(8193, new int[] { 2048, 2048, 2048, 2049 }),
				new LeafFixture(32768, new int[] { 8192, 8192, 8192, 8192 }),
				new LeafFixture(32769, new int[] { 8192, 8192, 8192, 2048, 2048, 2048, 2049 }),
				new LeafFixture(32770, new int[] { 8192, 2048, 2048, 2048, 2049, 8192, 2048, 2048, 2048, 2049 }),
				new LeafFixture(32771, new int[] { 8192, 2048, 2048, 2048, 2049, 8192, 2048, 2049, 2048, 2049 }),
				new LeafFixture(32772, repeatedLengths(4, 2048, 2048, 2048, 2049)),
				new LeafFixture(34904, repeatedLengths(4, 2181, 2182, 2181, 2182)),
				new LeafFixture(65536, repeatedLengths(16, 4096)) };
		for (LeafFixture fixture : fixtures) {
			ThreadLocal<ComparisonRange> admitted = new ThreadLocal<>();
			ConcurrentLinkedQueue<LeafRange> leaves = new ConcurrentLinkedQueue<>();
			AtomicInteger activations = new AtomicInteger();
			AtomicInteger closes = new AtomicInteger();
			Integer[] input = descending(fixture.length());
			Integer[] expected = input.clone();
			Arrays.sort(expected);
			try (QueryExecutionContext.Activation source = QueryExecutionContext.activateReplaySafepoint(() -> {
			}, () -> () -> {
				assertNull(admitted.get());
				ComparisonRange range = new ComparisonRange();
				admitted.set(range);
				activations.incrementAndGet();
				return () -> {
					assertSame(range, admitted.get());
					admitted.remove();
					closes.incrementAndGet();
					if (range.maximum >= 0 && range.adjacentOnly) {
						leaves.add(new LeafRange(range.minimum, range.maximum + 1));
					}
				};
			})) {
				ContextAwareArraySorter.sort(input, (left, right) -> {
					admitted.get().observe(fixture.length() - left, fixture.length() - right);
					return Integer.compare(left, right);
				}, QueryExecutionContext.captureReplayContext());
			}
			assertArrayEquals(expected, input, "all rows must sort at boundary " + fixture.length());
			assertEquals(activations.get(), closes.get());
			List<LeafRange> actual = new ArrayList<>(leaves);
			actual.sort(Comparator.comparingInt(LeafRange::start));
			List<LeafRange> expectedRanges = new ArrayList<>();
			int start = 0;
			for (int length : fixture.leafLengths()) {
				expectedRanges.add(new LeafRange(start, start + length));
				start += length;
			}
			assertEquals(fixture.length(), start, "the explicit fixture must cover every original row");
			assertEquals(expectedRanges, actual,
					"independent leaf comparison scopes must cover the exact adjacent quarters at " + fixture.length());
			assertNull(admitted.get());
		}
	}

	@Test
	void nestedSortingRestoresOuterCapabilityDeadlineAndDeferral() {
		ThreadLocal<String> admitted = new ThreadLocal<>();
		AtomicInteger outerCheckpoints = new AtomicInteger();
		AtomicInteger innerCheckpoints = new AtomicInteger();
		try (QueryExecutionDeadline outerDeadline = QueryExecutionDeadline.start(60000);
				QueryExecutionDeadline innerDeadline = QueryExecutionDeadline.start(60000);
				QueryExecutionDeadline.Scope deadlineScope = outerDeadline.enter();
				QueryExecutionContext.Activation outer = QueryExecutionContext.activateReplaySafepoint(
						outerCheckpoints::incrementAndGet, () -> capability(admitted, "outer"))) {
			Integer[] input = { 3, 2, 1 };
			ContextAwareArraySorter.sort(input, (left, right) -> {
				assertEquals("outer", admitted.get());
				assertSame(outerDeadline, QueryExecutionDeadline.current());
				try (QueryExecutionDeadline.Scope localDeadline = innerDeadline.enter();
						QueryExecutionContext.Activation inner = QueryExecutionContext.activateReplaySafepoint(
								innerCheckpoints::incrementAndGet, () -> capability(admitted, "inner"));
						QueryExecutionContext.Activation deferral = QueryExecutionContext.deferReplaySafepoints()) {
					int priorOuter = outerCheckpoints.get();
					Integer[] nested = { 2, 1 };
					ContextAwareArraySorter.sort(nested, (first, second) -> {
						assertEquals("inner", admitted.get());
						assertSame(innerDeadline, QueryExecutionDeadline.current());
						QueryExecutionContext.checkpointReplaySafepoint();
						return Integer.compare(first, second);
					}, QueryExecutionContext.captureReplayContext());
					assertArrayEquals(new Integer[] { 1, 2 }, nested);
					assertEquals(priorOuter, outerCheckpoints.get(), "captured deferral must cover nested sort tasks");
					assertEquals(0, innerCheckpoints.get());
					assertEquals("outer", admitted.get(), "nested tasks must restore the prior worker admission");
					assertSame(innerDeadline, QueryExecutionDeadline.current());
				}
				assertEquals("outer", admitted.get());
				assertSame(outerDeadline, QueryExecutionDeadline.current());
				return Integer.compare(left, right);
			}, QueryExecutionContext.captureReplayContext());
			assertArrayEquals(new Integer[] { 1, 2, 3 }, input);
			assertTrue(outerCheckpoints.get() > 0, "closing nested deferral must restore outer checkpoints");
			assertNull(admitted.get());
		}
		assertNull(QueryExecutionDeadline.current());
	}

