	@Test
	@Timeout(value = 20, unit = TimeUnit.SECONDS)
	void deadlineExpirationDuringAdmittedComparisonStopsTheSameAttempt() throws Exception {
		ExecutorService executor = Executors.newSingleThreadExecutor();
		CountDownLatch entered = new CountDownLatch(1);
		CountDownLatch release = new CountDownLatch(1);
		CountDownLatch expired = new CountDownLatch(1);
		AtomicInteger activeScopes = new AtomicInteger();
		try {
			executor.submit(() -> null).get(5, TimeUnit.SECONDS);
			try (QueryExecutionDeadline deadline = QueryExecutionDeadline.start(1000);
					QueryExecutionDeadline.Registration registration = deadline.onExpiration(expired::countDown)) {
				var result = executor.submit(() -> {
					try (QueryExecutionDeadline.Scope deadlineScope = deadline.enter();
							QueryExecutionContext.Activation source = QueryExecutionContext
									.activateReplaySafepoint(() -> {
									}, () -> () -> {
										activeScopes.incrementAndGet();
										return activeScopes::decrementAndGet;
									})) {
						ContextAwareArraySorter.sort(new Integer[] { 2, 1 }, (left, right) -> {
							assertSame(deadline, QueryExecutionDeadline.current());
							entered.countDown();
							await(release);
							return Integer.compare(left, right);
						}, QueryExecutionContext.captureReplayContext());
					}
				});
				assertTrue(entered.await(5, TimeUnit.SECONDS));
				assertTrue(expired.await(5, TimeUnit.SECONDS));
				release.countDown();
				ExecutionException failure = assertThrows(ExecutionException.class,
						() -> result.get(5, TimeUnit.SECONDS));
				assertEquals(QueryInterruptedException.class, failure.getCause().getClass());
				assertEquals("Query evaluation took too long", failure.getCause().getMessage());
				assertEquals(0, activeScopes.get(), "expired sorting must close admission before returning");
				executor.submit(() -> assertNull(QueryExecutionDeadline.current())).get(5, TimeUnit.SECONDS);
			}
		} finally {
			release.countDown();
			executor.shutdown();
			assertTrue(executor.awaitTermination(5, TimeUnit.SECONDS));
		}
	}

